custom_options:
{
  "x_field": "date",
  "chart_type": "Line",
  "y_axis_fields": [
    {
      "y_field": "tickets_sold",
      "name": "Tickets Sold",
      "color": "#22C55E",
      "stroke_width": 3,
      "fill": "rgba(34, 197, 94, 0.2)",
      "show_dots": true,
      "dot_size": 5
    },
    {
      "y_field": "total_revenue",
      "name": "Revenue (₹)",
      "color": "#3B82F6",
      "stroke_width": 3,
      "fill": "rgba(59, 130, 246, 0.15)",
      "show_dots": true,
      "dot_size": 5
    }
  ],
  "y_fields": ["tickets_sold", "total_revenue"],
  "colors": ["#22C55E", "#3B82F6"],
  "line_options": {
    "curve": "smooth"
  },
  "axis_options": {
    "x_axis_label": "Date",
    "y_axis_label": "Tickets / Revenue",
    "shorten_numbers": true
  },
  "tooltip_options": {
    "show_total": false,
    "background_color": "#1E293B",
    "text_color": "#F8FAFC",
    "border_radius": 6,
    "shadow": true,
    "format_tooltip_y": "function(y, field) { return field === 'total_revenue' ? '₹' + y.toLocaleString() : y; }"
  },
  "legend": {
    "position": "bottom",
    "align": "center",
    "label_color": "#475569"
  },
  "grid": {
    "visible": true,
    "color": "#E2E8F0"
  },
  "max_rows": 50
}
